static void msgbox_event_cb(lv_event_t *e)
{
	lv_obj_t *obj = lv_event_get_current_target(e);

	const char *txt =
		lv_msgbox_get_active_btn_text(obj);

	if (txt && strcmp(txt, "Forget") == 0)
	{
		platform_forget_wifi_creds();

		lv_label_set_text(
			uic_wifiName,
			"No WiFi Selected");

		lv_textarea_set_text(
			uic_wifiPassword,
			"");

		lv_textarea_set_text(
			uic_wifiStatus,
			"Not connected");
	}

	lv_msgbox_close(obj);
}

static void api_msgbox_event_cb(
	lv_event_t *e)
{
	lv_obj_t *obj =
		lv_event_get_current_target(e);

	const char *txt =
		lv_msgbox_get_active_btn_text(obj);

	if (txt &&
		strcmp(txt, "Forget") == 0)
	{
		platform_forget_opensky_creds();
		platform_restart();
	}

	lv_msgbox_close(obj);
}

void forgetWifi(lv_event_t *e)
{
	static const char *btns[] =
		{
			"Cancel",
			"Forget",
			""};

	lv_obj_t *mbox =
		lv_msgbox_create(
			NULL,
			"Forget WiFi?",
			"Stored WiFi credentials will be removed.\n And device will be resetarted",
			btns,
			false);

	lv_obj_center(mbox);

	lv_obj_add_event_cb(
		mbox,
		msgbox_event_cb,
		LV_EVENT_VALUE_CHANGED,
		NULL);
}

void Radar_SelectPrev(lv_event_t *e)
{
	if (gAircraftCount <= 0)
	{
		selectedAircraft = -1;
		return;
	}

	selectedAircraft--;

	if (selectedAircraft < 0)
	{
		selectedAircraft =
			gAircraftCount - 1;
	}

	strcpy(
		selectedIcao24,
		gAircraft[selectedAircraft].icao24);

	Radar_Refresh();
	UpdateSelectedAircraftUI();
}

void Radar_SelectNext(lv_event_t *e)
{
	if (gAircraftCount <= 0)
	{
		selectedAircraft = -1;
		return;
	}

	selectedAircraft++;

	if (selectedAircraft >= gAircraftCount)
	{
		selectedAircraft = 0;
	}

	strcpy(
		selectedIcao24,
		gAircraft[selectedAircraft].icao24);

	Radar_Refresh();
	UpdateSelectedAircraftUI();
}

