void toggleLabels(lv_event_t *e)
{
	lv_event_code_t code =
		lv_event_get_code(e);

	lv_obj_t *obj =
		lv_event_get_target(e);

	if (code == LV_EVENT_VALUE_CHANGED)
	{
		showAircraftLabels =
			lv_obj_has_state(
				obj,
				LV_STATE_CHECKED);

		Radar_Refresh();

		LV_LOG_USER(
			"Labels: %s",
			showAircraftLabels
				? "On"
				: "Off");
	}
}

