void toggleTrail(lv_event_t *e)
{
	lv_event_code_t code = lv_event_get_code(e);
	lv_obj_t *obj = lv_event_get_target(e);

	if (code == LV_EVENT_VALUE_CHANGED)
	{
		bool on = lv_obj_has_state(obj, LV_STATE_CHECKED);
		Radar_SetTrail(on);
		platform_storage_set_u8("radar", "trail", on ? 1 : 0);
		Radar_Refresh();
		LV_LOG_USER("Trail: %s", on ? "On" : "Off");
	}
}

/* Sync the right-rail trail switch (Screen1) with the state in NVS, called by
   LoadTrail() in app_state.c. */
void syncTrailSwitchState(void)
{
	/* Screen3 holds the canonical uic_SwitchTrail; Screen1 holds a peer
	   switch we keep in the same NVS-controlled state. Both must show the
	   same CHECKED flag. */
	extern lv_obj_t * ui_SwitchTrailRowMain;
	if (!ui_SwitchTrailRowMain) return;
	if (showSelectedTrail)
		lv_obj_add_state(ui_SwitchTrailRowMain, LV_STATE_CHECKED);
	else
		lv_obj_clear_state(ui_SwitchTrailRowMain, LV_STATE_CHECKED);
}

void rangeDown(lv_event_t *e)
{
	(void)e;
	SetRadarRange(GetRadarRange() - 10.0f);
}

void Radar_TapSelect(lv_event_t *e)
{
	lv_event_code_t code =
		lv_event_get_code(e);

	if (code != LV_EVENT_CLICKED)
		return;

	lv_indev_t *indev =
		lv_indev_get_act();

	if (!indev)
		return;

	lv_point_t pt;
	lv_indev_get_point(indev, &pt);

	int idx =
		Radar_PickAircraft(
			pt.x,
			pt.y);

	if (idx >= 0 && idx < gAircraftCount)
	{
		selectedAircraft = idx;

		strcpy(
			selectedIcao24,
			gAircraft[idx].icao24);

		UpdateSelectedAircraftUI();
		Radar_Refresh();
	}
}

